// Presentation-only floating labels. Numeric copy uses a single generated
// bitmap font; arbitrary words retain the browser game's ordinary atlas label.
// No game state, actions or text content are generated by this layer.
import {createBitmapText} from '@egret/engine/bitmapfont';
import {createSharedMaterial2D} from '@egret/engine';

export const FIXED_NUMBER_CHARACTERS='0123456789+-−.,/%:';
export const FIXED_SIGNED_INTEGER_CHARACTERS='0123456789+-';
const SMOOTH=createSharedMaterial2D({filter:'linear',mipmapFilter:'linear'});
export function isFixedGlyphText(value,characters=FIXED_NUMBER_CHARACTERS){
  const text=String(value??''),allowed=new Set(characters);
  return text.length>0&&text.length<=64&&[...text].every(char=>allowed.has(char));
}
export function normalizeFloatingLabel(entry){
  if(!entry||entry.key===undefined||entry.key===null)throw new TypeError('floating label key is required');
  const {key}=entry;
  const size=Number.isFinite(entry.size)&&entry.size>0?entry.size:25;
  const color=Number.isSafeInteger(entry.color)&&entry.color>=0&&entry.color<=0xffffff?entry.color:0xffffff;
  const alpha=Number.isFinite(entry.alpha)?Math.max(0,Math.min(1,entry.alpha)):1;
  return {key,text:String(entry.text??''),size,color,alpha};
}
// This is only a game policy flag for the engine's native scheduler, not a
// second scheduling queue. Reserve a known batch before submitting it so the
// predicate is true for early jobs as well as late jobs.
export function createTextWorkPressure(threshold=8){
  if(!Number.isSafeInteger(threshold)||threshold<1)throw new RangeError('invalid text pressure threshold');
  let pending=0;
  return {
    when:()=>pending>=threshold,
    begin(count){
      if(!Number.isSafeInteger(count)||count<0)throw new RangeError('invalid text batch count');
      pending+=count;let left=count;
      return ()=>{if(left>0){left--;pending--}};
    },
    get pending(){return pending}
  };
}
export async function createFloatingLabels({
  engine,browser,scope,parent,
  characters=FIXED_SIGNED_INTEGER_CHARACTERS,baseFontSize=48,fontFamilies=['Microsoft YaHei','sans-serif'],
  atlasFontFamily=fontFamilies[0]??'sans-serif',fontWeight=700,locale='zh-TW',
  letterSpacing,digitAdvanceRatio=characters===FIXED_SIGNED_INTEGER_CHARACTERS ? .58 : undefined,
  verticalOffsetRatio=.12,useFixed=true,textPressure,onError=()=>{}
}={}){
  if(!engine||!scope||!browser||!parent)throw new TypeError('floating label host is required');
  const owner=engine.createScope(),records=new Map(),alphabet=new Set(characters);
  const fixed=text=>text.length>0&&text.length<=64&&[...text].every(char=>alphabet.has(char));
  let font,closed=false,fontBuildMs=0,fixedCreated=0,atlasCreated=0,spacing=letterSpacing??-4;
  const report=error=>{try{onError(error)}catch{/* Presentation diagnostics do not change gameplay. */}};
  function retire(record){record.scope.dispose()}
  function dispose(){
    if(closed)return;closed=true;
    // BitmapText borrowers have to be disposed before the immutable page.
    for(const record of records.values())retire(record);
    records.clear();owner.dispose();
  }
  scope.use({dispose});
  if(useFixed){
    const started=performance.now();
    try{
      font=await browser.createGlyphFont({characters,fontSize:baseFontSize,fontFamilies,fontWeight,scope:owner});
      // The fixed glyph cell includes guard pixels and the widest symbol.
      // Signed integer labels can overlap the transparent guard areas to keep
      // the old compact numerical appearance. Other character sets opt in.
      if(letterSpacing===undefined&&Number.isFinite(digitAdvanceRatio))
        spacing=Math.min(0,baseFontSize*digitAdvanceRatio-font.font.glyphs[0].xAdvance);
    }catch(error){
      if(!closed)report(error);
      // A failed optional glyph page never removes the existing atlas-text
      // capability. No raw Canvas or second private text cache is created.
    }
    fontBuildMs=performance.now()-started;
  }
  function place(record){
    if(!record.node)return;
    record.node.x=record.x;record.node.y=record.y+(record.kind==='bitmap'?record.desired.size*verticalOffsetRatio:0);
    record.node.alpha=record.desired.alpha;
    if(record.kind==='bitmap'){
      const scale=record.desired.size/baseFontSize;
      record.node.scaleX=record.node.scaleY=scale;
    }
  }
  function style(value){
    return {text:value.text,fontFamily:atlasFontFamily,fontSize:value.size,lineHeight:value.size+4,
      fontWeight,color:value.color,locale};
  }
  function refreshAtlas(record){
    if(!record.label)return;
    const desired=record.desired,match=record.applied;
    if(match?.text===desired.text&&match.color===desired.color&&match.size===desired.size)return;
    record.applied=desired;record.label.set(style(desired));
    // A superseded revision is allowed; the owner keeps only the live label.
    void record.label.ready.catch(error=>{
      if(!record.scope.signal.aborted&&error?.name!=='AbortError')report(error);
    });
  }
  function make(value,kind,releasePressure){
    const entryScope=engine.createScope(),record={kind,scope:entryScope,desired:value,x:0,y:0};
    records.set(value.key,record);
    if(kind==='bitmap'){
      const picture=entryScope.use(createBitmapText({...font,text:value.text,color:value.color,
        letterSpacing:spacing,kerning:false,fallback:null}));
      for(const mesh of picture.meshes)mesh.sharedMaterial=SMOOTH;
      record.label=picture;record.applied=value;
      record.node=parent.addChild(picture.display);fixedCreated++;
    }else{
      atlasCreated++;
      record.pending=browser.createAtlasLabel({...style(value),scope:entryScope}).then(async label=>{
        if(closed||entryScope.signal.aborted||records.get(value.key)!==record)return;
        record.label=label;record.applied=value;
        record.node=parent.addChild(label.display);
        refreshAtlas(record);place(record);browser.invalidate();
        await label.ready.catch(error=>{
          if(!entryScope.signal.aborted&&error?.name!=='AbortError')report(error);
        });
      },error=>{
        if(!entryScope.signal.aborted)report(error);
      }).finally(()=>releasePressure?.());
    }
    return record;
  }
  function update(entries,project=entry=>[entry.x,entry.y]){
    if(closed)return;
    let changed=false;
    const values=entries.map(entry=>{
      const value=normalizeFloatingLabel(entry);
      return {entry,value,kind:font&&fixed(value.text)?'bitmap':'atlas'};
    });
    const active=new Set(values.map(({value})=>value.key));
    if(active.size!==values.length)throw new TypeError('duplicate floating label key');
    for(const [key,record] of records)if(!active.has(key)){retire(record);records.delete(key);changed=true}
    const atlasNew=values.filter(({value,kind})=>kind==='atlas'&&records.get(value.key)?.kind!=='atlas').length;
    const releasePressure=textPressure?.begin(atlasNew);
    let reserved=atlasNew;
    try{
      for(const {entry,value,kind} of values){
        let record=records.get(value.key);
        if(record&&record.kind!==kind){retire(record);records.delete(value.key);record=undefined;changed=true}
        if(!record){
          record=make(value,kind,kind==='atlas'?releasePressure:undefined);changed=true;
          if(kind==='atlas')reserved--;
        }
        const before=record.desired;
        if(before.text!==value.text||before.size!==value.size||before.color!==value.color||before.alpha!==value.alpha)changed=true;
        record.desired=value;
        if(kind==='bitmap'){
          if(record.applied.text!==value.text)record.label.text=value.text;
          if(record.applied.color!==value.color)record.label.color=value.color;
          record.applied=value;
        }else refreshAtlas(record);
        const [x,y]=project(entry);
        if(record.x!==x||record.y!==y)changed=true;
        record.x=x;record.y=y;place(record);
      }
    }finally{
      // A host validation failure may interrupt a batch before every label
      // is issued; return just the unused reservations.
      while(reserved-->0)releasePressure?.();
    }
    if(changed)browser.invalidate();
  }
  async function whenReady(){
    // Intended for loading diagnostics and isolated fixtures, never called
    // from the per-frame update. Live bitmap entries are synchronous.
    const snapshot=[...records.values()];
    await Promise.all(snapshot.map(record=>record.pending));
    await Promise.allSettled(snapshot.map(record=>record.kind==='atlas'?record.label?.ready:undefined));
  }
  return {
    update,dispose,whenReady,
    getStats(){
      const live=[...records.values()];
      return {fontReady:Boolean(font),fontBuildMs,baseFontSize,glyphAdvance:font?.font.glyphs[0]?.xAdvance,spacing,
        bitmap:live.filter(record=>record.kind==='bitmap').length,
        atlas:live.filter(record=>record.kind==='atlas').length,fixedCreated,atlasCreated,
        pending:live.filter(record=>record.kind==='atlas'&&!record.node).length};
    },
    getLabel(key){return records.get(key)?.label}
  };
}
